style.css:
@-moz-document regexp(".*") {
/* 1. Define MAXIDENT Design Tokens & Palette Variables */
    :root {
        /* Core Album Colors */
        --maxident-pink: #FF3E81;      /* Iconic T-CRUSH / Heart Monster Pink */
        --maxident-black: #121212;     /* Matte Heart Version Black */
        --maxident-grey: #8A8A8A;      /* Case Version Muted Base Grey */
        --maxident-white: #F9F9F9;     /* Clean Album Text Accent */
        --maxident-lime: #D2FF00;      /* Safety Slogan Neon Lime Highlight */
        
        /* Light Mode Defaults (Bright Backgrounds) */
        --global-text-color: var(--maxident-black) !important;
        --global-heading-color: var(--maxident-pink) !important;
        --global-link-color: var(--maxident-pink) !important;
        --global-selection-bg: var(--maxident-pink) !important;
        --global-selection-text: var(--maxident-white) !important;
    }

    /* 2. Dark Mode Overrides (Dark Backgrounds) */
    @media (prefers-color-scheme: dark) {
        :root {
            --global-text-color: var(--maxident-white) !important;
            --global-heading-color: var(--maxident-pink) !important;
            --global-link-color: var(--maxident-lime) !important;
            --global-selection-bg: var(--maxident-pink) !important;
            --global-selection-text: var(--maxident-black) !important;
        }
    }

    /* 3. Apply MAXIDENT Theming Globally to Every Element */
    *, *::before, *::after {
        /* Transitions prevent harsh color snapping when switching themes */
        transition: color 0.15s ease, border-color 0.15s ease !important;
    }

    /* Body and General Paragraph Text */
    body, p, li, span, div, td, input, textarea {
        color: var(--global-text-color) !important;
    }

    /* Headings get the vivid Album Pink treatment */
    h1, h2, h3, h4, h5, h6, strong, b {
        color: var(--global-heading-color) !important;
    }

    /* Hyperlinks adjust dynamically between Pink (Light) and Lime (Dark) for contrast */
    a, a * {
        color: var(--global-link-color) !important;
    }

    /* Custom MAXIDENT Highlight Behavior when selecting text */
    ::-moz-selection {
        background: var(--global-selection-bg) !important;
        color: var(--global-selection-text) !important;
    }
    ::selection {
        background: var(--global-selection-bg) !important;
        color: var(--global-selection-text) !important;
    }
}
